import json, sys

def trunc(s, n=500):
    s = str(s)
    if len(s) > n:
        return s[:n] + f"...[{len(s)-n} more chars]"
    return s

def main(path, outpath):
    out = []
    with open(path) as fh:
        for i, line in enumerate(fh):
            line = line.strip()
            if not line:
                continue
            try:
                d = json.loads(line)
            except Exception as e:
                continue
            t = d.get('type')
            ts = d.get('timestamp','')
            if t not in ('user','assistant'):
                continue
            msg = d.get('message', {})
            role = msg.get('role')
            content = msg.get('content')
            if isinstance(content, str):
                out.append(f"[{i}] {ts} {role} TEXT: {trunc(content, 800)}")
                continue
            if isinstance(content, list):
                for c in content:
                    if not isinstance(c, dict):
                        continue
                    ctype = c.get('type')
                    if ctype == 'text':
                        out.append(f"[{i}] {ts} {role} TEXT: {trunc(c.get('text',''), 800)}")
                    elif ctype == 'tool_use':
                        out.append(f"[{i}] {ts} {role} TOOL_USE: {c.get('name')} INPUT: {trunc(json.dumps(c.get('input',{})), 400)}")
                    elif ctype == 'tool_result':
                        cont = c.get('content')
                        if isinstance(cont, list):
                            cont = ' '.join(x.get('text','') for x in cont if isinstance(x, dict))
                        out.append(f"[{i}] {ts} {role} TOOL_RESULT: {trunc(cont, 400)}")
    with open(outpath, 'w') as fh:
        fh.write('\n'.join(out))
    print(f"wrote {len(out)} lines to {outpath}")

if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
PYEOF
