import json,sys

def truncate(s, n=300):
    s = s.replace("\n"," ")
    return s if len(s)<=n else s[:n]+"...[TRUNC]"

def main(path, outpath):
    out = open(outpath, "w")
    with open(path) as fh:
        for i,line in enumerate(fh):
            line=line.strip()
            if not line: continue
            try:
                d=json.loads(line)
            except Exception as e:
                continue
            t=d.get('type')
            ts=d.get('timestamp')
            if t not in ('user','assistant'):
                continue
            msg=d.get('message')
            if not isinstance(msg, dict):
                continue
            role = msg.get('role')
            content = msg.get('content')
            if isinstance(content, str):
                out.write(f"[{i}] {ts} {role} TEXT: {truncate(content)}\n")
                continue
            if isinstance(content, list):
                for c in content:
                    ctype = c.get('type') if isinstance(c,dict) else None
                    if ctype == 'text':
                        out.write(f"[{i}] {ts} {role} TEXT: {truncate(c.get('text',''))}\n")
                    elif ctype == 'tool_use':
                        name = c.get('name')
                        inp = truncate(json.dumps(c.get('input',{})), 250)
                        out.write(f"[{i}] {ts} {role} TOOL_USE: {name} INPUT: {inp}\n")
                    elif ctype == 'tool_result':
                        cont = c.get('content')
                        if isinstance(cont, list):
                            txt = " ".join(x.get('text','') for x in cont if isinstance(x,dict))
                        else:
                            txt = str(cont)
                        err = c.get('is_error')
                        out.write(f"[{i}] {ts} {role} TOOL_RESULT err={err}: {truncate(txt,300)}\n")
    out.close()

if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
EOF
