import json, sys

path = sys.argv[1]
maxlen = int(sys.argv[2]) if len(sys.argv) > 2 else 300

def trunc(s, n=maxlen):
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

with open(path) as f:
    for i, line in enumerate(f):
        line = line.strip()
        if not line:
            continue
        try:
            d = json.loads(line)
        except Exception:
            continue
        t = d.get('type')
        ts = d.get('timestamp', '')
        if t in ('user', 'assistant'):
            msg = d.get('message', {})
            role = msg.get('role', t)
            content = msg.get('content')
            if isinstance(content, str):
                print(f"[{i}] {ts} {role}: {trunc(content)}")
            elif isinstance(content, list):
                for c in content:
                    ctype = c.get('type')
                    if ctype == 'text':
                        print(f"[{i}] {ts} {role} TEXT: {trunc(c.get('text',''))}")
                    elif ctype == 'tool_use':
                        print(f"[{i}] {ts} {role} TOOL_USE: {c.get('name')} input={trunc(json.dumps(c.get('input',{})), 200)}")
                    elif ctype == 'tool_result':
                        cont = c.get('content')
                        if isinstance(cont, list):
                            cont = ' '.join(x.get('text','') if isinstance(x,dict) else str(x) for x in cont)
                        print(f"[{i}] {ts} {role} TOOL_RESULT: {trunc(cont)}")
                    else:
                        print(f"[{i}] {ts} {role} OTHER({ctype}): {trunc(c)}")
        elif t == 'summary':
            print(f"[{i}] SUMMARY: {trunc(d)}")

